      "category": "development"
    },
    {
      "name": "admob-integration",
      "description": "AdMob integration patterns for Android with Jetpack Compose. Use when implementing banner ads, interstitial ads, rewarded ads, or native ads in Android applications.",
      "source": "./skills/admob-integration",
      "category": "development"
    }
  ]
}
